+/** Bytes per unit, keyed by lowercase unit name (unit names are case insensitive). */
+const UNIT_BYTES: Record<string, number> = {
+  b: 1,
+  kb: 1000,
+  mb: 1000 ** 2,
+  gb: 1000 ** 3,
+  tb: 1000 ** 4,
+  kib: 1024,
+  mib: 1024 ** 2,
+  gib: 1024 ** 3,
+  tib: 1024 ** 4,
+};
+
+const DECIMAL_UNITS = ["B", "kB", "MB", "GB", "TB"];
+const BINARY_UNITS = ["B", "KiB", "MiB", "GiB", "TiB"];
+
+const SIZE_PATTERN = /^\s*(\d+(?:\.\d+)?)\s*([a-z]*)\s*$/i;
+
 /** Parse a size such as "1.5 kB" into bytes. See README.md for the units. */
 export function parseSize(text: string): number {
-  throw new Error("not implemented");
+  const match = SIZE_PATTERN.exec(text);
+  if (match === null) {
+    throw new RangeError(`invalid size: ${JSON.stringify(text)}`);
+  }
+
+  const [, digits, unit] = match;
+  const multiplier = unit === "" ? 1 : UNIT_BYTES[unit.toLowerCase()];
+  if (multiplier === undefined) {
+    throw new RangeError(`invalid size: unknown unit ${JSON.stringify(unit)} in ${JSON.stringify(text)}`);
+  }
+
+  return Math.round(Number(digits) * multiplier);
+}
+
+/** Format a number with `digits` decimals, dropping trailing zeros. */
+function formatNumber(value: number, digits: number): string {
+  const fixed = value.toFixed(digits);
+  return fixed.includes(".") ? fixed.replace(/\.?0+$/, "") : fixed;
 }

